use crate::error::Result;
use crate::session::{Message, ToolCall};
use async_trait::async_trait;
use futures::Stream;
use std::pin::Pin;

/// Asynchronous stream yielding individual tokens as generated by an LLM.
pub type TokenStream = Pin<Box<dyn Stream<Item = Result<String>> + Send>>;

/// Abstraction for language model inference backends.
#[async_trait]
pub trait InferenceProvider: Send + Sync {
    /// Identifier for this provider instance (e.g. "ollama", "llamacpp", "remote").
    fn provider_name(&self) -> &str;

    /// Active model name.
    fn model_name(&self) -> &str;

    /// Stream textual completions for the provided conversation history and tools.
    async fn stream_completion(
        &self,
        messages: &[Message],
        system_prompt: Option<&str>,
        tools: Option<&[serde_json::Value]>,
    ) -> Result<TokenStream>;

    /// Complete a single turn with direct structured tool calling analysis.
    async fn generate_response(
        &self,
        messages: &[Message],
        system_prompt: Option<&str>,
        tools: Option<&[serde_json::Value]>,
    ) -> Result<InferenceResponse>;
}

/// The outcome of an inference turn.
#[derive(Debug, Clone)]
pub struct InferenceResponse {
    pub content: String,
    pub tool_calls: Vec<ToolCall>,
    pub usage_tokens: Option<usize>,
}

/// Classification of tool security impact.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum PermissionTier {
    ReadOnly = 0,
    LowRisk = 1,
    ConfirmationRequired = 2,
    Restricted = 3,
}

/// Contract for executable tools.
#[async_trait]
pub trait Tool: Send + Sync {
    /// Unique identifier for the tool.
    fn name(&self) -> &str;

    /// Human-readable description for model context.
    fn description(&self) -> &str;

    /// JSON Schema describing input arguments.
    fn parameters_schema(&self) -> serde_json::Value;

    /// Required permission tier to run this tool.
    fn permission_tier(&self) -> PermissionTier;

    /// Execute the tool with validated arguments.
    async fn execute(&self, arguments: serde_json::Value) -> Result<serde_json::Value>;
}

/// Speech synthesis engine interface.
#[async_trait]
pub trait SpeechSynthesizer: Send + Sync {
    /// Synthesizes text into 16-bit 16kHz mono PCM audio bytes.
    async fn synthesize(&self, text: &str) -> Result<Vec<u8>>;
}

/// Speech-to-text recognition interface.
#[async_trait]
pub trait SpeechRecognizer: Send + Sync {
    /// Transcribes 16kHz mono PCM audio samples into text.
    async fn transcribe(&self, pcm_samples: &[i16]) -> Result<String>;
}

/// Persistent memory and context retrieval interface.
#[async_trait]
pub trait MemoryStore: Send + Sync {
    /// Store a message in the active session.
    async fn save_message(&self, message: &Message) -> Result<()>;

    /// Retrieve chronological messages for a session.
    async fn get_session_history(
        &self,
        session_id: &crate::session::SessionId,
        limit: usize,
    ) -> Result<Vec<Message>>;

    /// Search long-term memory facts via keyword / semantic match.
    async fn search_relevant_context(&self, query: &str, limit: usize) -> Result<Vec<String>>;

    /// Persist a key fact or user preference.
    async fn remember_fact(&self, category: &str, fact: &str) -> Result<()>;
}
